const INFO={
 Mel:{what:"Гормон темноты: шишковидная железа выделяет его вечером, когда гаснет свет. Он не усыпляет, как снотворное, а сообщает внутренним часам, что наступила ночь.",
  goals:{sleep:"Хорошо работает при джетлаге, сменном графике и у «сов», которым трудно уснуть рано. При обычной бессоннице сокращает засыпание всего на 7–10 минут."},
  forms:[["0,5–1 мг","best","Маленькие дозы работают не хуже больших и реже дают разбитость утром."],["Пролонгированный 2 мг","ok","Для пожилых людей, у которых своего мелатонина мало."],["3–10 мг","bad","Пользы больше нет, а утром чаще сонливость и головная боль."]],
  buy:"В исследованиях реальное количество мелатонина в добавках отличалось от этикетки от −80% до +400%. Бери аптечные препараты. С антикоагулянтами, при эпилепсии и депрессии — только с врачом."},
 Gar:{what:"Выдержанный экстракт чеснока (AGE) получают долгой выдержкой чеснока в спирте. В нём больше стабильных серосодержащих веществ, чем в свежем чесноке, и нет резкого запаха.",
  goals:{heart:"В метаанализах у людей с гипертонией снижает верхнее давление примерно на 8 мм, немного снижает холестерин и жёсткость артерий.",immune:"В небольших исследованиях простуда и грипп проходили легче и короче."},
  forms:[["Выдержанный экстракт (AGE, Kyolic)","best","На нём сделана большая часть исследований давления."],["Порошок чеснока со стандартизацией по аллицину","ok","Тоже рабочий, но пахнет и чаще вызывает изжогу."],["Чесночное масло","bad","Активных веществ мало, данных почти нет."]],
  buy:"Разжижает кровь: прекрати за неделю до операции и не совмещай с антикоагулянтами без врача."},
 Beet:{what:"Свекла, руккола и шпинат богаты нитратами. Бактерии во рту превращают их в нитриты, а организм — в оксид азота, который расширяет сосуды и делает работу мышц экономнее.",
  goals:{heart:"Снижает давление на 4–5 мм на несколько часов после приёма.",energy:"Улучшает выносливость на 1–3%, у любителей сильнее, чем у профессионалов."},
  forms:[["Концентрированный шот","best","Известная доза нитратов в маленьком объёме."],["Обычный свекольный сок 500 мл","ok","Работает, но объём большой и много сахара."],["Порошок свеклы","bad","Нитратов часто почти нет, и на этикетке их обычно не указывают."]],
  buy:"Моча может окраситься в красный. Это безопасно."},
 Hib:{what:"Каркаде — чай из цветков гибискуса. В нём много антоцианов, которые мягко расширяют сосуды, и он работает как слабое мочегонное.",
  goals:{heart:"В небольших исследованиях 2–3 чашки в день снижали верхнее давление на 5–7 мм у людей с повышенным давлением."},
  forms:[["Заварной чай из цветков","best","Именно его изучали в исследованиях."],["Экстракт в капсулах","ok","Данных меньше, дозы разные."]],
  buy:"Может усилить действие мочегонных и таблеток от давления. При беременности не пить."},
 Rho:{what:"Растение северных гор, адаптоген. Активные вещества — розавины и салидрозид. Используют против усталости при стрессе.",
  goals:{energy:"В небольших исследованиях снижает усталость и истощение при стрессе и нагрузках.",brain:"Помогает при умственной усталости: на сменах, на экзаменах, при недосыпе.",sleep:"Снижает ощущение стресса и выгорания. Пить утром: вечером может мешать уснуть."},
  forms:[["Стандартизированный экстракт (3% розавинов, 1% салидрозида), например SHR-5","best","Самый изученный вариант."],["Нестандартизированный порошок корня","bad","Состав неизвестен, встречаются подделки из других видов родиолы."]]},
 Saf:{what:"Специя из рылец крокуса. Экстракт действует на серотонин и дофамин.",
  goals:{sleep:"В метаанализах 30 мг экстракта в день снижают тревожность и немного улучшают сон.",brain:"Улучшает настроение при лёгкой и умеренной депрессии, в нескольких исследованиях сравнимо с антидепрессантами. Исследования небольшие."},
  forms:[["Стандартизированный экстракт (affron и аналоги), 28–30 мг","best","Изученные дозы и формы."],["Шафран как специя","bad","В еде доза слишком мала. Дешёвый шафран часто подделка."]],
  buy:"Больше 1,5 г шафрана в день токсично. С антидепрессантами — только с врачом."},
 Bac:{what:"Аюрведическое растение для памяти. Активные вещества — бакозиды, они защищают нейроны и улучшают передачу сигналов.",
  goals:{brain:"В метаанализах улучшает запоминание и скорость обработки информации после 8–12 недель приёма. Быстрого эффекта, как от кофе, не даёт."},
  forms:[["Стандартизированный экстракт (Synapsa, BacoMind), 300 мг","best","На них сделаны исследования."],["Порошок травы","bad","Мало бакозидов и риск тяжёлых металлов."]],
  buy:"Частые побочки: тошнота, вздутие, иногда сонливость. Пей с едой."},
 BA:{what:"Аминокислота, из которой мышцы делают карнозин. Карнозин гасит кислоту, которая копится при интенсивной работе и вызывает жжение в мышцах.",
  goals:{energy:"Через 4 недели приёма улучшает результат в усилиях от 1 до 4 минут: интервалы, гребля, бег на 400–1500 м.",bones:"В силовых даёт 1–2 лишних повтора в длинных подходах. Для максимальной силы почти бесполезен."},
  forms:[["Обычный бета-аланин дробно","best","По 1,5–2 г 2–3 раза в день с едой, почти без покалывания."],["Пролонгированный (CarnoSyn SR)","ok","Меньше покалывания, но дороже."],["Разовая доза перед тренировкой","bad","Работает накопление за недели, а не разовый приём. Покалывание от предтренировочных комплексов — побочка, а не признак эффекта."]]},
 Bic:{what:"Обычная пищевая сода. Повышает буферную ёмкость крови и помогает выводить кислоту из мышц при максимальных усилиях.",
  goals:{energy:"Улучшает результат в интенсивных усилиях на 1–7 минут примерно на 2%. Для обычных тренировок не нужен."},
  forms:[["Капсулы с содой за 2–3 часа, с едой","best","Меньше проблем с желудком, чем раствор."],["Раствор соды в воде","ok","Работает, но часто вызывает тошноту и понос."]],
  buy:"В дозе много натрия. При повышенном давлении и болезнях почек не используй."},
 Prot:{what:"Белок молочной сыворотки. Быстро усваивается и богат лейцином, который запускает рост мышц. По сути это просто еда в удобной форме.",
  goals:{bones:"Помогает добрать 1,6–2,2 г белка на кг веса, без которых силовые дают меньше результата. У пожилых помогает сохранить мышцы."},
  forms:[["Изолят","best","90% белка, почти без лактозы. Подходит, если от молока вздутие."],["Концентрат","ok","Дешевле, 70–80% белка, есть немного лактозы."],["Гидролизат","ok","Усваивается быстрее, но горче и дороже. Для обычных целей это переплата."],["Протеин без независимых анализов","bad","Встречается подмешивание дешёвых аминокислот и тяжёлые металлы. Ищи сертификаты Informed Sport или NSF."]]},
 Psy:{what:"Растворимая клетчатка из шелухи семян подорожника. В воде превращается в гель, который замедляет всасывание сахара и связывает желчные кислоты.",
  goals:{heart:"10 г в день снижают «плохой» холестерин ЛПНП на 5–10%.",energy:"Сглаживает скачки сахара после еды и надолго даёт сытость: меньше провалов энергии и тяги к перекусам."},
  forms:[["Шелуха псиллиума (husk)","best","Чистая форма с нейтральным вкусом."],["Порошок с сахаром и ароматизаторами","bad","Сахар сводит пользу на нет."]],
  buy:"Начинай с 3–5 г и пей много воды. Без воды бывают вздутие и запор."},
 Pro:{what:"Живые полезные бактерии. Эффект зависит от конкретного штамма: разные штаммы работают на разные задачи.",
  goals:{immune:"В метаанализах немного снижают число простуд и их длительность. Ещё помогают избежать поноса при приёме антибиотиков."},
  forms:[["Изученные штаммы (L. rhamnosus GG, S. boulardii, B. lactis BB-12)","best","Под каждую задачу есть свои исследованные штаммы."],["Кефир, йогурт, квашеная капуста","best","Живые продукты тоже дают бактерии и разнообразие микрофлоры."],["Капсулы «50 миллиардов, 20 штаммов»","bad","Большое число на упаковке не означает больше пользы."]],
  buy:"При тяжёлом иммунодефиците — только по назначению врача."},
 D3:{what:"Гормоноподобный витамин. Управляет всасыванием кальция, работой иммунных клеток и мышц, рецепторы к нему есть почти во всех тканях. Кожа делает его на солнце, но на широтах выше примерно 40° с октября по март солнце стоит слишком низко.",
  goals:{bones:"Без D3 кальций из еды почти не всасывается, и кости со временем теряют плотность. У пожилых с дефицитом D3 вместе с кальцием снижает риск переломов.",immune:"При дефиците ежедневный приём снижает риск простуд и ОРВИ, это показал большой метаанализ. Если уровень в норме, эффекта почти нет."},
  forms:[["D3 (холекальциферол)","best","Та же форма, что делает кожа. Поднимает уровень в крови сильнее и дольше, чем D2."],["D3 в масле или в капсуле с маслом","best","Всасывается лучше сухих таблеток."],["D2 (эргокальциферол)","bad","Растительная форма, работает слабее и короче."],["Ударные дозы раз в месяц (50 000 МЕ и больше)","bad","Работают хуже ежедневных, а очень большие разовые дозы у пожилых даже повышали риск падений."]],
  buy:"Целевой уровень 25(OH)D обычно 30–60 нг/мл (75–150 нмоль/л). Пересдай анализ через 2–3 месяца после начала приёма."},
 K2:{what:"Активирует белки, которые встраивают кальций в кости и не дают ему оседать в стенках сосудов. K1 из зелени в основном работает на свёртываемость крови, K2 — на кости и сосуды.",
  goals:{bones:"Активирует остеокальцин, который встраивает кальций в кости. В японских исследованиях K2 снижал риск переломов, у европейцев результаты слабее.",heart:"Активирует белок MGP, который мешает кальцию откладываться в артериях. В наблюдениях больше K2 в еде — меньше кальциноза сосудов, но клинические испытания пользу пока не подтвердили."},
  forms:[["MK-7 (all-trans)","best","Держится в крови несколько дней, хватает 90–200 мкг раз в день. Ищи пометку all-trans: cis-форма почти не работает."],["MK-4","ok","Работает, но выводится за несколько часов. В исследованиях на кости давали очень большие дозы, 45 мг в день."],["K1 (филлохинон)","bad","Для костей и сосудов почти бесполезен, его и так хватает из зелени."]]},
 A:{what:"Нужен для зрения в темноте, здоровья кожи и слизистых и работы иммунных клеток. В еде есть готовый ретинол (печень, яйца, молочка) и бета-каротин из оранжевых овощей, который организм переводит в ретинол по мере нужды.",
  goals:{immune:"Слизистые носа, горла и кишечника — первый барьер против инфекций, и без витамина A они слабеют. При дефиците люди чаще болеют, особенно дети. При нормальном питании добавка иммунитет не усиливает."},
  forms:[["Бета-каротин","best","Организм берёт сколько нужно, передозировки нет. Но курильщикам большие дозы в добавках повышали риск рака лёгких."],["Ретинола пальмитат или ацетат","ok","Работает сразу, но копится в печени. Долго больше 3000 мкг в день вредно для печени и костей, при беременности опасно."],["Комплексы с большой дозой ретинола","bad","Если ещё ешь печень или пьёшь рыбий жир из печени трески, легко превысить безопасную дозу."]]},
 E:{what:"Жирорастворимый антиоксидант, защищает мембраны клеток от окисления. Витамин E — это восемь веществ: четыре токоферола и четыре токотриенола. Главный для человека — альфа-токоферол.",
  goals:{immune:"Поддерживает работу T-клеток. У пожилых умеренная доза (около 200 МЕ) в исследовании снижала число простуд. Молодым при нормальном питании не нужен.",infl:"Гасит окисление жиров в мембранах, которое запускает воспаление. В исследованиях на людях противовоспалительный эффект добавок слабый."},
  forms:[["d-альфа-токоферол (натуральный)","best","Натуральная форма, работает примерно в 1,4–2 раза сильнее синтетической."],["Смесь токоферолов (mixed tocopherols)","best","Есть ещё гамма-токоферол. Большая доза одного альфа-токоферола снижает гамма-токоферол в крови."],["Токотриенолы","ok","Интересны в исследованиях на клетках, на людях данных мало, стоят дорого."],["dl-альфа-токоферол (синтетический)","bad","Приставка dl означает синтетику: половина молекул почти не работает."]]},
 C:{what:"Водорастворимый антиоксидант. Нужен для синтеза коллагена (кожа, сосуды, связки), помогает всасывать железо и поддерживает иммунные клетки. Организм его не запасает, лишнее выходит с мочой.",
  goals:{immune:"При регулярном приёме простуда проходит примерно на 8% быстрее. Риск заболеть он не снижает, кроме людей под тяжёлой нагрузкой: у марафонцев и военных на учениях в холоде риск падал вдвое."},
  forms:[["Аскорбиновая кислота","best","Самая изученная и дешёвая форма, работает не хуже остальных."],["Аскорбат натрия или кальция (буферный)","ok","Мягче для желудка, если от кислоты изжога."],["Липосомальный","ok","Даёт немного больше в крови, но стоит в разы дороже."],["Ester-C, «натуральный из ацеролы»","bad","Переплата: преимуществ перед обычной аскорбинкой не доказано."]]},
 B1:{what:"Нужен, чтобы клетки получали энергию из глюкозы. Особенно важен для мозга, нервов и сердца. Дефицит бывает при алкоголе, диабете, приёме мочегонных и однообразной еде.",
  goals:{energy:"Без B1 углеводы плохо превращаются в энергию: появляются усталость и раздражительность. При нормальном уровне добавка бодрости не прибавит.",brain:"Мозг питается глюкозой, поэтому при дефиците B1 страдают память и концентрация. Бенфотиамин изучают при диабетической нейропатии и болезни Альцгеймера, данные пока предварительные."},
  forms:[["Бенфотиамин","best","Жирорастворимая форма, даёт в крови в несколько раз больше тиамина."],["Тиамина гидрохлорид или мононитрат","ok","Обычная дешёвая форма, подходит для профилактики."],["Сульбутиамин","ok","Лучше проникает в мозг, но изучен мало."]]},
 B6:{what:"Участвует более чем в 100 реакциях: синтез серотонина, дофамина, ГАМК и мелатонина, обмен белков и гомоцистеина.",
  goals:{brain:"Нужен для синтеза серотонина, дофамина и ГАМК. При дефиците хуже настроение, сон и концентрация.",energy:"Помогает доставать глюкозу из запасов в мышцах и печени. При нормальном уровне бодрости не добавляет."},
  forms:[["P5P (пиридоксаль-5-фосфат)","best","Активная форма, печени не нужно её переделывать."],["Пиридоксина гидрохлорид","ok","Дешёвая форма. Именно с её большими дозами связывают онемение рук и ног."],["Больше 25–50 мг в день надолго","bad","Опасно для нервов. В ЕС верхний безопасный предел снизили до 12 мг в день."]]},
 B9:{what:"Нужен для деления клеток, синтеза ДНК, кроветворения и обмена гомоцистеина. Особенно важен при планировании беременности.",
  goals:{heart:"Вместе с B12 и B6 снижает гомоцистеин, высокий уровень которого связан с инсультом. В большом китайском исследовании фолиевая кислота снижала риск инсульта у людей с повышенным давлением.",brain:"При дефиците растёт риск депрессии и ухудшается память. Метилфолат иногда добавляют к лечению депрессии."},
  forms:[["L-метилфолат (5-MTHF)","best","Готовая активная форма. Подходит людям с вариантом гена MTHFR, у которых фолиевая кислота превращается хуже."],["Фолиевая кислота","ok","Синтетическая, отлично изучена и работает у большинства. Больше 1000 мкг в день не нужно."],["Фолиновая кислота","ok","Тоже хорошо усваивается, чаще встречается в лекарствах."]]},
 B12:{what:"Нужен для нервной системы, кроветворения и синтеза ДНК. Есть только в продуктах животного происхождения. Хуже всасывается при гастрите, после 50 лет, на метформине и препаратах от изжоги.",
  goals:{energy:"Дефицит вызывает анемию: слабость, одышку, бледность. После восполнения энергия возвращается. Если уровень в норме, «энергетические» уколы B12 не нужны.",brain:"При долгом дефиците страдают нервы и память, немеют руки и ноги, бывает депрессия. Повреждения могут остаться навсегда, поэтому дефицит важно не пропустить."},
  forms:[["Цианокобаламин","best","Самая стабильная и изученная форма, отлично работает. Цианида в нём ничтожно мало."],["Метилкобаламин","ok","Активная форма, работает так же, но менее стабилен. Хороший выбор, но переплачивать не обязательно."],["Гидроксокобаламин, аденозилкобаламин","ok","Тоже рабочие. Гидроксокобаламин часто колют при сильном дефиците."],["Под язык или спрей","ok","Работает не лучше обычной таблетки: в больших дозах B12 и так всасывается."]]},
 Ca:{what:"Основной материал костей и зубов. Нужен для сокращения мышц, работы нервов и свёртывания крови. Лучше всего получать из еды: молочка, сыр, кунжут, капуста, сардины с костями.",
  goals:{bones:"При нехватке кальция организм забирает его из костей. Добавка помогает, если с едой получаешь меньше 700 мг в день. Если ешь молочку, обычно не нужна."},
  forms:[["Цитрат кальция","best","Всасывается и натощак, и при низкой кислотности желудка, реже вызывает запоры."],["Кальций из еды","best","Безопаснее таблеток: с большими дозами в добавках связывают камни в почках."],["Карбонат кальция","ok","Дешевле, и кальция в нём больше, но пить только с едой. Чаще вздутие и запоры."],["Доломит, кальций из ракушек и костной муки","bad","Могут содержать свинец."]]},
 Mg:{what:"Участвует более чем в 300 реакциях: выработка энергии, работа мышц и нервов, ритм сердца, сон. Много в орехах, семечках, бобовых, тёмной зелени и какао. Дефицит частый: стресс, кофе, алкоголь и пот вымывают магний.",
  goals:{sleep:"Успокаивает нервную систему и помогает рецепторам ГАМК. Сильнее всего помогает тем, кому магния не хватает: пожилым, людям под стрессом. Если уровень в норме, эффект на сон скромный.",heart:"Нужен для ровного ритма сердца, немного снижает давление (на 2–4 мм рт. ст. в метаанализах). При дефиците бывают перебои в сердце и судороги.",bones:"Около 60% магния тела хранится в костях. Нужен для активации витамина D и работы мышц, иногда помогает при ночных судорогах в ногах."},
  forms:[["Глицинат (бисглицинат)","best","Хорошо усваивается, мягкий для желудка, глицин дополнительно успокаивает. Лучший выбор для сна и стресса."],["Цитрат","best","Хорошо усваивается и дешевле. В больших дозах слабит."],["Таурат","ok","Магний и таурин в одной форме, интересен для сердца и давления."],["Треонат (L-треонат, Magtein)","ok","В опытах на животных лучше проникает в мозг. На людях данных мало, а магния в капсуле немного."],["Малат","ok","Часто советуют при усталости и боли в мышцах, данных немного."],["Лактат, хлорид","ok","Нормально усваиваются, встречаются реже."],["Оксид","bad","Самый дешёвый: магния в нём много, а усваивается мало. Работает больше как слабительное."],["Сульфат (английская соль)","bad","Внутрь — это слабительное. Годится только для ванн, но через кожу магний почти не всасывается."]]},
 Zn:{what:"Нужен для иммунитета, заживления ран, кожи, вкуса и обоняния, выработки тестостерона и спермы. Больше всего его в устрицах, красном мясе и тыквенных семечках. Теряется с потом.",
  goals:{immune:"Пастилки с цинком (около 75 мг в день), если начать в первые сутки, сокращают простуду примерно на треть. Постоянный приём нужен только при дефиците."},
  forms:[["Пиколинат, бисглицинат","best","Хорошо усваиваются, мягче для желудка."],["Цитрат, глюконат, ацетат","ok","Дешёвые и рабочие. Глюконат и ацетат — лучший выбор для пастилок от простуды."],["Оксид","bad","Усваивается хуже всех, часто встречается в дешёвых комплексах."],["Цинк в спрее для носа","bad","Может навсегда отбить обоняние. Не используй."]]},
 Cu:{what:"Нужна для образования крови, коллагена, работы нервов и иммунитета. Обычно хватает из еды: печень, орехи, какао, семечки. Добавка нужна в основном, если долго пьёшь цинк.",
  goals:{energy:"Нужна для обмена железа и работы митохондрий. При дефиците меди бывают анемия и усталость, которые не проходят от одного железа."},
  forms:[["Бисглицинат меди","best","Хорошо усваивается."],["Глюконат, сульфат","ok","Дешёвые и рабочие формы."],["Оксид меди","bad","Почти не всасывается."]]},
 Fe:{what:"Входит в гемоглобин, который носит кислород по крови, и в ферменты мышц. Из мяса железо всасывается на 15–35%, из растений на 2–20%. Лишнее железо организм не выводит, поэтому пить его без анализа опасно.",
  goals:{energy:"При дефиците железа (низкий ферритин) бывают усталость, одышка, выпадение волос и холодные руки, даже если гемоглобин ещё в норме. После восполнения это проходит."},
  forms:[["Бисглицинат железа","best","Хорошо всасывается, реже тошнота и запоры."],["Приём через день","best","Всасывается больше: после дозы печень почти на сутки тормозит всасывание гормоном гепсидином."],["Сульфат железа","ok","Дешёвый и изученный стандарт, но часто бьёт по желудку."],["Железо с медленным высвобождением","bad","Всасывается хуже, переплата за технологию."]],
  buy:"Сначала сдай ферритин. Ниже 30 нг/мл — дефицит. Если выше 100–150 без явной причины, железо пить нельзя."},
 Se:{what:"Нужен для щитовидной железы и антиоксидантных ферментов. Почвы во многих регионах, включая большую часть Европы, бедны селеном, поэтому дефицит встречается.",
  goals:{immune:"Нужен для работы иммунных клеток. При дефиците организм хуже справляется с вирусами. Если уровень в норме, добавка не помогает."},
  forms:[["Селенометионин","best","Хорошо усваивается, запасается в тканях."],["Дрожжи с селеном","ok","Рабочий вариант, но состав плавает от партии к партии."],["Селенит натрия","ok","Усваивается хуже, но в обычных дозах безопасен."],["Бразильский орех","ok","1–2 ореха дают суточную норму, но содержание сильно плавает."],["Больше 200 мкг в день надолго","bad","Риск отравления: выпадение волос, ломкие ногти. По некоторым данным, растёт риск диабета."]]},
 I:{what:"Из йода щитовидная железа делает гормоны, которые управляют обменом веществ, энергией и температурой тела. Во многих регионах йода в еде и воде мало, поэтому полезна йодированная соль.",
  goals:{energy:"При нехватке йода щитовидная железа работает хуже: усталость, зябкость, лишний вес, сухая кожа. Но если ТТГ в норме, добавка энергии не прибавит."},
  forms:[["Йодированная соль","best","Самый простой способ закрыть норму. Соли в конце готовки, при нагреве йод улетучивается."],["Йодид калия","best","Стандартная форма в таблетках, 100–150 мкг."],["Ламинария, келп","bad","Йода в них может быть в десятки раз больше нормы, а это вредит щитовидной железе."]]},
 O3:{what:"Жирные кислоты EPA и DHA — строительный материал мембран мозга, сетчатки и сердца. Организм почти не умеет делать их сам. Главный источник — жирная морская рыба: скумбрия, сельдь, лосось, сардины.",
  goals:{infl:"Из EPA и DHA организм делает вещества, которые гасят воспаление. В исследованиях от 2 г в день снижаются СРБ и боль в суставах при артрите.",heart:"Дозы 2–4 г в день снижают триглицериды на 20–30%. Очищенный EPA в дозе 4 г снизил риск инфаркта и инсульта у людей с высоким риском. Обычные профилактические дозы дают слабый эффект.",brain:"DHA — главный жир мозга. Добавки умеренно помогают при депрессии, лучше работают формулы с преобладанием EPA. Для памяти у здоровых людей эффект небольшой."},
  forms:[["Триглицериды (rTG) или фосфолипиды (масло криля)","best","Усваиваются лучше, особенно если пьёшь не с жирной едой."],["Этиловые эфиры (EE)","ok","Самая частая и дешёвая форма. Нормально работает, если пить с жирной едой."],["Масло печени трески","ok","EPA и DHA мало, зато много витамина A. Следи за дозой ретинола."],["Льняное масло (ALA)","bad","В EPA превращается всего 5–10%, в DHA меньше 1%. Рыбу не заменяет."],["Дешёвый рыбий жир без анализов","bad","Часто окислен. От прогорклого жира отрыжка рыбой и расстройство желудка, а пользы нет. Если капсула сильно пахнет рыбой, не пей."]],
  buy:"Смотри на сумму EPA и DHA на порцию, а не на «1000 мг рыбьего жира»: там часто всего 300 мг EPA+DHA. Ищи сертификат IFOS или низкий показатель окисления TOTOX. Храни в холодильнике."},
 Cur:{what:"Главное активное вещество куркумы. Действует на те же пути воспаления, что и некоторые обезболивающие, но слабее. Сам по себе почти не всасывается.",
  goals:{infl:"В метаанализах уменьшает боль и скованность при артрозе, местами сравнимо с ибупрофеном, но эффект слабее и наступает медленнее. Снижает СРБ. Работает только в усваиваемой форме."},
  forms:[["Фитосомальный (Meriva), мицеллярный, Longvida, Theracurmin","best","Усваиваются в разы лучше, перец не нужен. На них сделана большая часть исследований."],["С пиперином (BioPerine)","best","Дешёвый способ поднять усвоение."],["Порошок куркумы","bad","Куркумина в нём всего 2–5%, и он почти не всасывается. Как специя хорош, как лечение нет."],["Дешёвые экстракты без анализов","bad","Встречаются подделки с красителями и свинцом. Бери бренды с проверкой независимой лабораторией."]]},
 Pip:{what:"Алкалоид чёрного перца. Тормозит ферменты печени и кишечника, которые разрушают многие вещества, и так повышает их уровень в крови. Сам по себе как добавка не нужен.",
  goals:{},
  forms:[["Экстракт BioPerine, 5–10 мг","best","Стандартная доза в добавках с куркумином."],["Вместе с лекарствами","bad","Может повышать уровень некоторых лекарств в крови (антикоагулянтов, противосудорожных и других). Если пьёшь таблетки, спроси врача."]]},
 Q10:{what:"Нужен митохондриям, чтобы делать энергию, и работает как антиоксидант. С возрастом и на статинах его становится меньше.",
  goals:{energy:"Участвует в выработке энергии в клетках. Помогает при дефиците: на статинах, при некоторых болезнях митохондрий. Здоровым молодым людям бодрости обычно не добавляет.",heart:"При сердечной недостаточности 300 мг в день в исследовании Q-SYMBIO снизили смертность. На статинах иногда уменьшает боль в мышцах, но данные смешанные.",long:"Уровень Q10 падает с возрастом. В шведском исследовании на пожилых Q10 вместе с селеном снизил смертность от болезней сердца. Это одно исследование, нужны подтверждения."},
  forms:[["Убихинол","best","Восстановленная форма, лучше усваивается после 40 лет и при болезнях. Дороже."],["Q10 в масле (капсулы с жидкостью)","best","Сухой порошок почти не всасывается, в масле — намного лучше."],["Убихинон","ok","Стандартная форма, на ней сделано большинство исследований. Пить только с жирной едой."]]},
 Cre:{what:"Запас быстрой энергии для мышц и мозга. Организм делает около 1 г в день, ещё 1–2 г даёт мясо и рыба. Добавка поднимает запасы в мышцах на 20–40%. Одна из самых изученных и безопасных добавок.",
  goals:{bones:"Вместе с силовыми прибавляет силу и мышечную массу, у пожилых помогает сохранить мышцы. Без тренировок эффекта почти нет.",brain:"Улучшает память и мышление при недосыпе и стрессе, у вегетарианцев и пожилых. Сейчас изучается при сотрясениях мозга.",energy:"Помогает в коротких мощных усилиях: подходах, спринтах, прыжках. Меньше устаёшь между повторами."},
  forms:[["Моногидрат","best","Самая изученная форма, дешёвая и рабочая. Знак Creapure означает чистый немецкий моногидрат."],["Микронизированный моногидрат","best","То же самое, просто лучше растворяется."],["Загрузка 20 г в день неделю","ok","Быстрее насыщает мышцы, но через месяц 3–5 г в день дают тот же результат."],["HCl, этиловый эфир, Kre-Alkalyn, «креатиновые матрицы»","bad","Дороже, а работают не лучше моногидрата. Этиловый эфир даже хуже."]]},
 Gly:{what:"Самая простая аминокислота. Нужна для коллагена, глутатиона и работы нервной системы, в мозге работает как успокаивающий медиатор.",
  goals:{sleep:"3 г перед сном немного снижают температуру тела, а это сигнал ко сну. В небольших японских исследованиях люди быстрее засыпали и были бодрее утром.",long:"У мышей глицин продлевал жизнь на 4–6%. Вместе с NAC восстанавливает глутатион, уровень которого с возрастом падает."},
  forms:[["Порошок глицина","best","3 г — это около чайной ложки. Дешевле капсул, сладкий на вкус, легко растворяется в воде."],["Аптечные таблетки 100 мг под язык","bad","Доза в 30 раз меньше, чем в исследованиях."]]},
 NAD:{what:"NAD+ нужен митохондриям для выработки энергии и ферментам, которые чинят ДНК. С возрастом его уровень падает. NMN и NR — вещества, из которых организм делает NAD+.",
  goals:{long:"У старых мышей повышение NAD+ улучшало обмен веществ и выносливость. У людей NMN и NR надёжно поднимают NAD+ в крови, но явной пользы для здоровья пока не нашли.",energy:"В теории больше NAD+ — лучше работают митохондрии. В исследованиях на людях эффект на выносливость и силу небольшой или отсутствует."},
  forms:[["NR (никотинамид рибозид, Niagen)","best","Лучше всего изучен на людях."],["NMN","ok","Тоже рабочий, исследований на людях меньше."],["Никотинамид (витамин B3)","ok","Дешёвый предшественник, тоже поднимает NAD+."],["NAD+ в капсулах","bad","Целиком почти не всасывается, предшественники работают лучше."],["Ниацин в больших дозах","bad","Тоже поднимает NAD+, но вызывает сильные приливы жара и нагружает печень."]]},
 Api:{what:"Флавоноид из ромашки, петрушки и сельдерея. Связывается с теми же рецепторами в мозге, что и успокоительные, только гораздо слабее.",
  goals:{sleep:"Именно он даёт успокаивающий эффект ромашкового чая. Исследования экстракта ромашки на сон небольшие, эффект умеренный. Чистый апигенин на людях почти не изучен.",long:"Подавляет фермент CD38, который с возрастом разрушает NAD+. У старых мышей это поднимало NAD+ и улучшало обмен веществ. На людях не проверено."},
  forms:[["Чай или экстракт ромашки","best","Изучен лучше чистого апигенина и стоит копейки."],["Апигенин 50 мг в капсулах","ok","Самый частый вариант. Данных о правильной дозе для людей мало."],["Больше 100 мг в день","bad","Пользы не доказано, а с гормональными препаратами возможны взаимодействия."]]},
 NAC:{what:"Форма аминокислоты цистеина. Из неё организм делает глутатион, главный внутренний антиоксидант. В медицине NAC используют как средство от кашля (разжижает мокроту) и как противоядие при отравлении парацетамолом.",
  goals:{long:"С возрастом глутатион падает. В небольших исследованиях на пожилых связка глицина и NAC (GlyNAC) поднимала глутатион, улучшала силу, чувствительность к инсулину и ряд маркеров старения. Это работы одной группы учёных, нужны подтверждения.",infl:"Глутатион гасит окислительный стресс, который поддерживает воспаление. NAC снижает число обострений бронхита у курильщиков и людей с ХОБЛ. По другим воспалениям данных меньше."},
  forms:[["NAC в капсулах 600 мг","best","Стандартная форма. Пахнет серой, это нормально."],["Шипучие таблетки от кашля","ok","Тот же NAC, только с сахаром или подсластителями."],["Глутатион в капсулах","bad","Большая часть разрушается в кишечнике. NAC с глицином работает надёжнее."]]},
 Tau:{what:"Аминокислота, которой много в сердце, мозге, мышцах и сетчатке. Регулирует воду и кальций в клетках и успокаивает нервную систему. Есть в мясе и рыбе, немного делает сам организм.",
  goals:{long:"В исследовании 2023 года (журнал Science) уровень таурина падал с возрастом, а добавки продлевали мышам жизнь на 10–12% и улучшали здоровье старых обезьян. У людей это пока только связь, а не доказательство.",heart:"Небольшие исследования показывают снижение давления и пользу при сердечной недостаточности."},
  forms:[["Порошок таурина","best","Дёшево, легко растворяется, вкус нейтральный."],["Капсулы","ok","Удобно, но для дозы 2–3 г нужно много капсул."],["Энергетики","bad","Таурина в них около 1 г, но вместе с сахаром и большой дозой кофеина."]]},
 LT:{what:"Аминокислота из чайных листьев. Усиливает альфа-ритм мозга, который связан со спокойным сосредоточением. Поэтому чай бодрит мягче, чем кофе.",
  goals:{brain:"Сам по себе слабо улучшает внимание. С кофеином в соотношении примерно 2:1 улучшает концентрацию и скорость реакции и убирает нервозность от кофе.",sleep:"200 мг снижают тревожность и помогают расслабиться, но не вызывают сонливости. В небольших исследованиях улучшали качество сна."},
  forms:[["Suntheanine","best","Чистый L-теанин, на нём сделано большинство исследований."],["Обычный L-теанин","ok","Тоже работает, если у производителя есть анализы."],["DL-теанин, дешёвый экстракт зелёного чая","bad","D-форма не работает и может мешать L-форме, а в экстрактах теанина часто мало."]]},
 Ash:{what:"Корень растения из аюрведы, адаптоген. Снижает гормон стресса кортизол и действует на ГАМК-рецепторы. У мужчин в небольших исследованиях немного повышала тестостерон и качество спермы.",
  goals:{sleep:"В нескольких исследованиях 300–600 мг в день снижали стресс, тревожность и кортизол на 15–30% и улучшали сон. Одна из лучше изученных трав для стресса."},
  forms:[["KSM-66","best","Экстракт корня, самый изученный."],["Sensoril, Shoden","ok","Экстракты корня и листьев с большим количеством активных веществ. Тоже изучены, но меньше."],["Порошок корня без стандартизации","bad","Сколько в нём активных веществ, неизвестно."]],
  buy:"Бывают редкие случаи поражения печени. Нельзя при беременности. Может повышать гормоны щитовидной железы. После 2–3 месяцев приёма делай перерыв."},
 Cof:{what:"Кофеин блокирует рецепторы аденозина — вещества, которое копится за день и вызывает сонливость. Ещё в кофе много полифенолов.",
  goals:{brain:"Улучшает внимание, скорость реакции и настроение. Люди, которые пьют 2–4 чашки в день, реже болеют Паркинсоном и депрессией, но это наблюдения.",energy:"Снижает усталость и улучшает результаты тренировок на 2–4%. Действует 5–6 часов, поэтому кофе после 14:00 может мешать сну."},
  forms:[["Фильтр-кофе, эспрессо","best","Бумажный фильтр задерживает кафестол, который повышает холестерин."],["Зелёный и чёрный чай","best","Кофеина меньше, зато есть L-теанин."],["Френч-пресс, турка","ok","Больше кафестола: при 4 чашках в день и больше немного растёт холестерин."],["Энергетики","bad","Много сахара и кофеина за раз."]]},
 GTE:{what:"Экстракт листьев зелёного чая, главное вещество в нём — катехин EGCG (это полифенол). Тормозит фермент COMT, который разрушает норадреналин, поэтому сигнал «сжигай жир» держится дольше.",
  goals:{energy:"В метаанализах вместе с кофеином давал минус 1–1,5 кг за 2–3 месяца. Эффект небольшой и работает только на фоне дефицита калорий.",heart:"Немного снижает ЛПНП и давление, но эффект маленький."},
  forms:[["Экстракт с указанным EGCG, до 300–400 мг в день","best","С едой. Видно, сколько EGCG получаешь."],["Заварной зелёный чай, 3–4 чашки","best","Безопасно, хотя EGCG меньше."],["Высокие дозы, от 800 мг EGCG, натощак","bad","Описаны случаи повреждения печени, EFSA предупреждает об этих дозах."],["Жиросжигатели с экстрактом чая","bad","Обычно лошадиная доза кофеина и неизвестно сколько EGCG."]]},
 Coc:{what:"Какао-бобы богаты флаванолами (эпикатехином и др.) — это полифенолы. Они повышают выработку оксида азота в сосудах, и сосуды лучше расширяются.",
  goals:{heart:"Одни из лучших данных среди полифенолов: в исследованиях 400–900 мг флаванолов в день улучшали эластичность сосудов и немного снижали давление. В большом исследовании COSMOS брали 500 мг.",brain:"Улучшает кровоток в мозге. Есть небольшие данные об улучшении памяти у пожилых, особенно если в питании мало флаванолов."},
  forms:[["Натуральный порошок (non-alkalized, raw cacao)","best","1–2 столовые ложки (10–20 г). Флаванолов много, сахара нет. Не заливай кипятком."],["Капсулы с указанными «cocoa flavanols, мг»","best","Точная доза, как в исследованиях."],["Алкализованный (Dutch-processed) какао","bad","Подщелачивание уничтожает большую часть флаванолов."],["Шоколад, даже 85%","ok","Флаванолов меньше, а калорий много — в основном за счёт жира."]],
  buy:"На вес почти не влияет. Пить ради похудения смысла нет."},
 Res:{what:"Полифенол из кожицы красного винограда и японского горца. Стал знаменит после опытов на мышах и дрожжах, где он включал «гены долголетия» (сиртуины).",
  goals:{long:"У людей данные слабые: метаанализы находят крошечное снижение веса и окружности талии, на грани шума. Продление жизни у людей не показано."},
  forms:[["Транс-ресвератрол из японского горца, с пиперином","ok","Пиперин немного улучшает всасывание."],["Красное вино как источник","bad","Ресвератрола там очень мало, а алкоголь вредит сильнее."]],
  buy:"Ради похудения брать не стоит: из полифенолов у него самый слабый эффект на вес."},
};

